-- OPERATOR ONLY: separate supervised maintenance approval; all writers drained.
-- Deploy the dual-layout application BEFORE this SQL. Never run old app on bigint.
-- Verify fresh business AND private configuration recovery, plus local inverse.
BEGIN;
SET LOCAL lock_timeout='10s'; SET LOCAL statement_timeout='120s';
SET LOCAL standard_conforming_strings=on;
SELECT 1/coalesce(current_setting('stock.allow_bill_identity_conversion',true)='reviewed-order-bill-bigint-v1',false)::int;
SELECT 1/coalesce(current_setting('stock.bill_identity_restore_verified',true)='business-and-config-v1',false)::int;
SELECT 1/coalesce(current_setting('stock.bill_identity_source',true)~'^[a-f0-9]{40}$' AND current_setting('stock.bill_identity_source',true)<>repeat('0',40),false)::int;
SELECT 1/coalesce(current_setting('stock.bill_identity_fingerprint',true)~'^[a-f0-9]{64}$' AND current_setting('stock.bill_identity_fingerprint',true)<>repeat('0',64),false)::int;
SELECT pg_advisory_xact_lock(835107241); SELECT pg_advisory_xact_lock(835107242);
LOCK TABLE stock_operational.order_bills IN ACCESS EXCLUSIVE MODE;
SELECT 1/coalesce((SELECT isolation_id::text=current_setting('stock.expected_isolation_id',true) AND purpose=current_setting('stock.expected_purpose',true) AND purpose IN ('production','isolated-staging') FROM stock_operational.environment WHERE singleton),false)::int;
SELECT 1/coalesce((SELECT value::text=current_setting('stock.bill_identity_revision',true) FROM stock_operational.revision WHERE singleton FOR UPDATE),false)::int;
SELECT 1/(NOT EXISTS(SELECT FROM pg_prepared_xacts WHERE database=current_database()))::int;
SELECT 1/((SELECT relowner=current_user::regrole AND relrowsecurity AND NOT relforcerowsecurity FROM pg_class WHERE oid='stock_operational.order_bills'::regclass))::int;
SELECT 1/(NOT EXISTS(SELECT FROM pg_constraint WHERE contype='f' AND confrelid='stock_operational.order_bills'::regclass))::int;
SELECT 1/coalesce((SELECT NOT prosecdef AND md5(prosrc)='06b583f4c94b4fa2de5c06406a877fdc' FROM pg_proc WHERE oid=to_regprocedure('stock_operational.lexeme_mapping_contract_v1()')),false)::int;
SELECT 1/(stock_operational.lexeme_mapping_contract_v1()='typed' AND stock_operational.soft_delete_contract_v1()='deletedAt' AND stock_operational.media_record_contract_v1()='id-only')::int;
SELECT 1/coalesce((SELECT atttypid='text'::regtype AND attidentity='' AND attnotnull AND NOT atthasdef FROM pg_attribute WHERE attrelid='stock_operational.order_bills'::regclass AND attname='id' AND NOT attisdropped),false)::int;
SELECT 1/(to_regclass('stock_operational.order_bills_id_seq') IS NULL)::int;
-- Replace only the exact released text-only CHECK; never drop unknown checks.
SELECT 1/((SELECT count(*)=1 AND bool_and(convalidated AND conislocal AND coninhcount=0 AND NOT connoinherit AND obj_description(oid,'pg_constraint') IS NULL AND pg_get_expr(conbin,conrelid)=$expr$(id <> ''::text)$expr$) FROM pg_constraint WHERE conrelid='stock_operational.order_bills'::regclass AND conname='order_bills_id_check' AND contype='c'))::int;
-- Include soft-deleted rows; reject aliases, overflow and exhausted capacity.
SELECT 1/(NOT EXISTS(SELECT FROM stock_operational.order_bills WHERE NOT CASE WHEN id ~ '^(0|[1-9][0-9]{0,18})$' THEN id::numeric<9223372036854775807 ELSE false END))::int;
ALTER TABLE stock_operational.order_bills DROP CONSTRAINT order_bills_id_check;
ALTER TABLE stock_operational.order_bills ALTER COLUMN id TYPE bigint USING id::bigint;
ALTER TABLE stock_operational.order_bills ADD CONSTRAINT order_bills_id_check CHECK(id>=0);
ALTER TABLE stock_operational.order_bills ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME stock_operational.order_bills_id_seq START WITH 2 MINVALUE 1 NO CYCLE);
-- New sequence only: never alter another table's sequence or row/global revision.
SELECT setval('stock_operational.order_bills_id_seq',greatest(coalesce(max(id),1),1),true) FROM stock_operational.order_bills;
REVOKE ALL ON SEQUENCE stock_operational.order_bills_id_seq FROM PUBLIC,anon,authenticated;
-- Default ACLs must not silently add unreviewed readers/writers to this object.
SELECT 1/(NOT EXISTS(SELECT FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('S',c.relowner))) a WHERE c.oid='stock_operational.order_bills_id_seq'::regclass AND a.grantee<>c.relowner AND a.grantee NOT IN(SELECT oid FROM pg_roles WHERE rolname IN('stock_runtime','stock_prod_backup'))))::int;
REVOKE ALL ON SEQUENCE stock_operational.order_bills_id_seq FROM stock_runtime;
GRANT USAGE ON SEQUENCE stock_operational.order_bills_id_seq TO stock_runtime;
DO $$BEGIN
 IF EXISTS(SELECT FROM pg_roles WHERE rolname='stock_prod_backup') THEN
  REVOKE ALL ON SEQUENCE stock_operational.order_bills_id_seq FROM stock_prod_backup;
  GRANT SELECT ON SEQUENCE stock_operational.order_bills_id_seq TO stock_prod_backup;
 END IF;
END$$;
